INSERT INTO `courses` VALUES (1,'A01 - HTML5 Komprehensif: Dari Nol Pengenalan Hingga Mahir Membangun Web Semantik','Kurikulum terlengkap belajar HTML5 dari tingkat pemula tanpa pengalaman koding hingga mahir merancang arsitektur website semantik modern. Membahas tuntas standar W3C, meta SEO, tipografi, tabel data, formulir validasi, media responsif, dan aksesibilitas WAI-ARIA.',0.00,NULL,1,'end','free',1,1,1,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(2,'A02 - CSS3 Komprehensif: Seni Menata Desain Web, Flexbox, Grid & Animasi UI','Eksplorasi mendalam desain antarmuka modern. Dari pemahaman selektor CSS, specificity, universal box-sizing, tipografi cairan (clamp), Flexbox 1 dimensi, CSS Grid 2 dimensi, teknik positioning (sticky/fixed), media queries mobile-first, hingga micro-interactions animasi transisi.',75000.00,NULL,1,'end','free',1,1,1,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(3,'A03 - JavaScript ES6+ Komprehensif: Logika Pemrograman, Manipulasi DOM & Aplikasi Web Modern','Kuasai bahasa pemrograman inti web dari fondasi fundamental hingga teknik modern. Pelajari variabel let/const, operator perbandingan ketat, struktur logika percabangan, fungsi modern & arrow functions, manipulasi array mutakhir (map, filter, reduce), interaktivitas dokumen DOM, penanganan event dinamis, hingga pemrograman asynchronous dengan Fetch API dan async/await.',99000.00,NULL,1,'end','free',1,1,1,'2026-10-24 20:00:31','2026-10-24 20:00:31');
