INSERT INTO `course_htmls` VALUES (1,1,'Live Demo: Komponen Formulir Registrasi & Validasi Real-Time','Eksplorasi antarmuka formulir interaktif dengan validasi HTML5 bawaan, styling kartu gelap modern, dan indikator status pengiriman.','<div class=\"demo-card\">\n    <div class=\"demo-header\">\n        <span class=\"badge\">LIVE FORM VALIDATION</span>\n        <h2>Formulir Pendaftaran Siswa</h2>\n        <p>Uji validasi HTML5 bawaan dengan mencoba mengosongkan input atau memasukkan format email yang salah.</p>\n    </div>\n\n    <form class=\"student-form\" onsubmit=\"event.preventDefault(); document.getElementById(\'alertSuccess\').style.display=\'block\';\">\n        <div class=\"form-group\">\n            <label for=\"txtName\">Nama Lengkap <span class=\"req\">*</span></label>\n            <input type=\"text\" id=\"txtName\" required minlength=\"3\" placeholder=\"Contoh: Budi Santoso\" class=\"form-input\">\n        </div>\n\n        <div class=\"form-group\">\n            <label for=\"txtEmail\">Email Resmi <span class=\"req\">*</span></label>\n            <input type=\"email\" id=\"txtEmail\" required placeholder=\"budi@kantor.com\" class=\"form-input\">\n        </div>\n\n        <div class=\"form-row\">\n            <div class=\"form-group half\">\n                <label for=\"txtPeminatan\">Peminatan <span class=\"req\">*</span></label>\n                <select id=\"txtPeminatan\" required class=\"form-input\">\n                    <option value=\"\">Pilih Jalur</option>\n                    <option value=\"frontend\">Frontend Engineering</option>\n                    <option value=\"backend\">Backend Engineering</option>\n                    <option value=\"fullstack\">Full-Stack Development</option>\n                </select>\n            </div>\n            <div class=\"form-group half\">\n                <label for=\"txtPengalaman\">Pengalaman Coding</label>\n                <select id=\"txtPengalaman\" class=\"form-input\">\n                    <option value=\"nol\">Pemula (Belum Pernah)</option>\n                    <option value=\"dasar\">Pernah Belajar Dasar</option>\n                    <option value=\"mahir\">Sudah Menengah</option>\n                </select>\n            </div>\n        </div>\n\n        <button type=\"submit\" class=\"submit-btn\">Kirim Pendaftaran Sekarang</button>\n\n        <div id=\"alertSuccess\" class=\"alert-success\" style=\"display: none;\">\n            ✔ Berhasil! Seluruh data input memenuhi validasi standar HTML5 dan siap diproses server.\n        </div>\n    </form>\n</div>','.demo-card { max-width: 560px; margin: 30px auto; background: #0b1329; border: 1px solid #1e293b; border-radius: 20px; padding: 32px; color: #fff; font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif; box-shadow: 0 20px 45px rgba(0,0,0,0.6); }\n.badge { display: inline-block; background: rgba(56, 189, 248, 0.1); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.3); font-size: 10px; font-weight: 800; padding: 4px 12px; border-radius: 20px; margin-bottom: 12px; letter-spacing: 1px; }\n.demo-header h2 { font-size: 22px; font-weight: 800; margin: 0 0 6px 0; color: #fff; }\n.demo-header p { font-size: 12px; color: #94a3b8; margin: 0 0 24px 0; line-height: 1.5; }\n.student-form { display: flex; flex-direction: column; gap: 16px; }\n.form-group { display: flex; flex-direction: column; gap: 6px; }\n.form-row { display: flex; gap: 14px; }\n.form-group.half { flex: 1; }\nlabel { font-size: 12px; font-weight: 700; color: #cbd5e1; }\n.req { color: #ef4444; }\n.form-input { background: #030712; border: 1px solid #334155; border-radius: 10px; padding: 12px 14px; color: #fff; font-size: 13px; outline: none; transition: border-color 0.2s; }\n.form-input:focus { border-color: #38bdf8; box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.15); }\n.submit-btn { margin-top: 8px; background: linear-gradient(135deg, #0284c7, #0369a1); color: #fff; border: none; border-radius: 10px; padding: 13px; font-weight: 800; font-size: 13px; cursor: pointer; transition: all 0.2s; }\n.submit-btn:hover { background: linear-gradient(135deg, #0ea5e9, #0284c7); box-shadow: 0 6px 20px rgba(14, 165, 233, 0.3); }\n.alert-success { background: rgba(16, 185, 129, 0.15); border: 1px solid #10b981; color: #34d399; padding: 12px; border-radius: 10px; font-size: 12px; font-weight: 700; text-align: center; margin-top: 10px; }','console.log(\"HTML5 Demo Form Initialized\");',8,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(2,2,'Live Demo: Dashboard Statistik Glassmorphism & Grid Responsif','Eksplorasi antarmuka dashboard dengan CSS Grid responsif, efek latar belakang buram (Glassmorphism), dan indikator metrik yang dinamis.','<div class=\"stats-grid\">\n    <div class=\"stat-card\">\n        <div class=\"stat-icon icon-blue\">👥</div>\n        <div class=\"stat-info\">\n            <span class=\"stat-label\">Total Pengguna Aktif</span>\n            <span class=\"stat-value\">12.450</span>\n            <span class=\"stat-badge badge-up\">▲ +14% bulan ini</span>\n        </div>\n    </div>\n\n    <div class=\"stat-card\">\n        <div class=\"stat-icon icon-green\">🎓</div>\n        <div class=\"stat-info\">\n            <span class=\"stat-label\">Kelulusan Kursus</span>\n            <span class=\"stat-value\">98.2%</span>\n            <span class=\"stat-badge badge-up\">▲ Sangat Optimal</span>\n        </div>\n    </div>\n\n    <div class=\"stat-card\">\n        <div class=\"stat-icon icon-amber\">⭐</div>\n        <div class=\"stat-info\">\n            <span class=\"stat-label\">Rating Rata-Rata</span>\n            <span class=\"stat-value\">4.9 / 5.0</span>\n            <span class=\"stat-badge badge-star\">★ 2.100 Ulasan</span>\n        </div>\n    </div>\n</div>','.stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; max-width: 900px; margin: 30px auto; padding: 15px; font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif; }\n.stat-card { background: rgba(15, 23, 42, 0.75); backdrop-filter: blur(12px); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 18px; padding: 22px; display: flex; align-items: center; gap: 18px; box-shadow: 0 15px 35px rgba(0,0,0,0.4); transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.3s; }\n.stat-card:hover { transform: translateY(-5px); border-color: rgba(56, 189, 248, 0.4); box-shadow: 0 20px 40px rgba(56, 189, 248, 0.1); }\n.stat-icon { width: 52px; height: 52px; border-radius: 14px; display: flex; align-items: center; justify-content: center; font-size: 24px; flex-shrink: 0; }\n.icon-blue { background: rgba(56, 189, 248, 0.15); border: 1px solid rgba(56, 189, 248, 0.3); }\n.icon-green { background: rgba(16, 185, 129, 0.15); border: 1px solid rgba(16, 185, 129, 0.3); }\n.icon-amber { background: rgba(245, 158, 11, 0.15); border: 1px solid rgba(245, 158, 11, 0.3); }\n.stat-info { display: flex; flex-direction: column; gap: 4px; }\n.stat-label { font-size: 11px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px; }\n.stat-value { font-size: 24px; font-weight: 900; color: #fff; letter-spacing: -0.5px; }\n.stat-badge { font-size: 10px; font-weight: 800; padding: 2px 8px; border-radius: 6px; width: fit-content; margin-top: 2px; }\n.badge-up { background: rgba(16, 185, 129, 0.12); color: #34d399; }\n.badge-star { background: rgba(245, 158, 11, 0.12); color: #fbbf24; }','console.log(\"CSS Dashboard Grid Loaded\");',8,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(3,3,'Live Lab: Mini Web App Task Tracker Interaktif dengan Manipulasi DOM & State','Eksplorasi pembuatan aplikasi Todo List interaktif menggunakan manipulasi DOM murni, event delegation, dan manajemen state berbasis data array.','<div class=\"app-card\">\n  <div class=\"app-header\">\n    <h3>✨ Pro Task Tracker</h3>\n    <span id=\"task-badge\" class=\"badge\">0 Tugas</span>\n  </div>\n\n  <div class=\"input-group\">\n    <input type=\"text\" id=\"task-input\" placeholder=\"Ketik aktivitas baru lalu tekan enter...\">\n    <button id=\"add-btn\" class=\"btn-primary\">Tambah</button>\n  </div>\n\n  <div class=\"filter-group\">\n    <button class=\"filter-btn active\" data-filter=\"all\">Semua</button>\n    <button class=\"filter-btn\" data-filter=\"pending\">Aktif</button>\n    <button class=\"filter-btn\" data-filter=\"completed\">Selesai</button>\n  </div>\n\n  <ul id=\"task-list\" class=\"task-list\"></ul>\n\n  <div class=\"app-footer\">\n    <span id=\"status-summary\">Belum ada tugas tercatat.</span>\n    <button id=\"clear-completed-btn\" class=\"btn-text\">Hapus Selesai</button>\n  </div>\n</div>\n\n<style>\n.app-card {\n  max-width: 480px;\n  margin: 1.5rem auto;\n  background: #ffffff;\n  border-radius: 16px;\n  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);\n  padding: 1.5rem;\n  font-family: system-ui, -apple-system, sans-serif;\n  color: #1e293b;\n}\n.app-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 1.25rem;\n}\n.app-header h3 {\n  margin: 0;\n  font-size: 1.25rem;\n  font-weight: 700;\n  color: #0f172a;\n}\n.badge {\n  background: #e0e7ff;\n  color: #4338ca;\n  font-size: 0.75rem;\n  font-weight: 600;\n  padding: 0.25rem 0.6rem;\n  border-radius: 9999px;\n}\n.input-group {\n  display: flex;\n  gap: 0.5rem;\n  margin-bottom: 1rem;\n}\n.input-group input {\n  flex: 1;\n  padding: 0.65rem 0.9rem;\n  border: 1.5px solid #cbd5e1;\n  border-radius: 8px;\n  font-size: 0.875rem;\n  outline: none;\n  transition: border-color 0.2s;\n}\n.input-group input:focus {\n  border-color: #4f46e5;\n}\n.btn-primary {\n  background: #4f46e5;\n  color: #ffffff;\n  border: none;\n  padding: 0.65rem 1.1rem;\n  border-radius: 8px;\n  font-weight: 600;\n  font-size: 0.875rem;\n  cursor: pointer;\n  transition: background-color 0.2s;\n}\n.btn-primary:hover {\n  background: #4338ca;\n}\n.filter-group {\n  display: flex;\n  gap: 0.4rem;\n  margin-bottom: 1rem;\n}\n.filter-btn {\n  background: #f1f5f9;\n  border: none;\n  padding: 0.35rem 0.75rem;\n  border-radius: 6px;\n  font-size: 0.75rem;\n  font-weight: 600;\n  color: #64748b;\n  cursor: pointer;\n}\n.filter-btn.active {\n  background: #0f172a;\n  color: #ffffff;\n}\n.task-list {\n  list-style: none;\n  padding: 0;\n  margin: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 0.5rem;\n  min-height: 120px;\n}\n.task-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.65rem 0.85rem;\n  background: #f8fafc;\n  border: 1px solid #e2e8f0;\n  border-radius: 8px;\n  transition: all 0.2s;\n}\n.task-item.completed {\n  background: #f1f5f9;\n  opacity: 0.7;\n}\n.task-item.completed .task-text {\n  text-decoration: line-through;\n  color: #94a3b8;\n}\n.task-left {\n  display: flex;\n  align-items: center;\n  gap: 0.65rem;\n}\n.btn-delete {\n  background: transparent;\n  border: none;\n  color: #ef4444;\n  cursor: pointer;\n  font-size: 1rem;\n}\n.app-footer {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-top: 1.25rem;\n  padding-top: 0.75rem;\n  border-top: 1px solid #f1f5f9;\n  font-size: 0.75rem;\n  color: #64748b;\n}\n.btn-text {\n  background: none;\n  border: none;\n  color: #6366f1;\n  font-size: 0.75rem;\n  cursor: pointer;\n  font-weight: 600;\n}\n.btn-text:hover {\n  text-decoration: underline;\n}\n</style>\n\n<script>\n(function() {\n  const state = {\n    tasks: [\n      { id: 1, text: \"Kuasai selektor querySelector di DOM\", done: true },\n      { id: 2, text: \"Pahami implementasi event listener submit\", done: false },\n      { id: 3, text: \"Latihan Higher-order function array map/filter\", done: false }\n    ],\n    filter: \"all\"\n  };\n\n  const listEl = document.getElementById(\"task-list\");\n  const inputEl = document.getElementById(\"task-input\");\n  const addBtn = document.getElementById(\"add-btn\");\n  const badgeEl = document.getElementById(\"task-badge\");\n  const summaryEl = document.getElementById(\"status-summary\");\n  const clearBtn = document.getElementById(\"clear-completed-btn\");\n  const filterBtns = document.querySelectorAll(\".filter-btn\");\n\n  function render() {\n    listEl.innerHTML = \"\";\n    const filtered = state.tasks.filter(t => {\n      if (state.filter === \"pending\") return !t.done;\n      if (state.filter === \"completed\") return t.done;\n      return true;\n    });\n\n    if (filtered.length === 0) {\n      listEl.innerHTML = `<li style=\"text-align: center; color: #94a3b8; padding: 1.5rem 0; font-size: 0.875rem;\">Tidak ada tugas pada kategori ini.</li>`;\n    } else {\n      filtered.forEach(task => {\n        const li = document.createElement(\"li\");\n        li.className = \"task-item \" + (task.done ? \"completed\" : \"\");\n        li.innerHTML = `\n          <div class=\"task-left\">\n            <input type=\"checkbox\" \\${task.done ? \"checked\" : \"\"} data-id=\"\\${task.id}\" class=\"task-toggle\">\n            <span class=\"task-text\">\\${task.text}</span>\n          </div>\n          <button class=\"btn-delete\" data-id=\"\\${task.id}\" title=\"Hapus tugas\">&times;</button>\n        `;\n        listEl.appendChild(li);\n      });\n    }\n\n    const pendingCount = state.tasks.filter(t => !t.done).length;\n    badgeEl.textContent = `\\${state.tasks.length} Total`;\n    summaryEl.textContent = `\\${pendingCount} tugas aktif tersisa`;\n  }\n\n  function addTask() {\n    const val = inputEl.value.trim();\n    if (!val) return;\n    state.tasks.push({ id: Date.now(), text: val, done: false });\n    inputEl.value = \"\";\n    render();\n  }\n\n  addBtn.addEventListener(\"click\", addTask);\n  inputEl.addEventListener(\"keypress\", (e) => {\n    if (e.key === \"Enter\") addTask();\n  });\n\n  listEl.addEventListener(\"click\", (e) => {\n    const id = Number(e.target.dataset.id);\n    if (!id) return;\n\n    if (e.target.classList.contains(\"task-toggle\")) {\n      const item = state.tasks.find(t => t.id === id);\n      if (item) item.done = !item.done;\n      render();\n    } else if (e.target.classList.contains(\"btn-delete\")) {\n      state.tasks = state.tasks.filter(t => t.id !== id);\n      render();\n    }\n  });\n\n  filterBtns.forEach(btn => {\n    btn.addEventListener(\"click\", () => {\n      filterBtns.forEach(b => b.classList.remove(\"active\"));\n      btn.classList.add(\"active\");\n      state.filter = btn.dataset.filter;\n      render();\n    });\n  });\n\n  clearBtn.addEventListener(\"click\", () => {\n    state.tasks = state.tasks.filter(t => !t.done);\n    render();\n  });\n\n  render();\n})();\n</script>',NULL,NULL,8,'2026-10-24 20:00:31','2026-10-24 20:00:31');
