/*!40000 ALTER TABLE `course_questions` DISABLE KEYS */;
INSERT INTO `course_questions` VALUES (1,1,'question','Tujuan Deklarasi <!DOCTYPE html>','Mengapa setiap dokumen web HTML5 wajib diawali dengan baris kode `<!DOCTYPE html>` pada baris pertamanya?','[\"Menghubungkan dokumen ke server internet secara otomatis\", \"Menginstruksikan peramban agar merender halaman dalam mode standar (standards mode) dan mencegah mode kompatibilitas kuno\", \"Mengimpor pustaka font eksternal dari CDN Google\", \"Mengaktifkan fitur enkripsi data transaksi perbankan\"]','Menginstruksikan peramban agar merender halaman dalam mode standar (standards mode) dan mencegah mode kompatibilitas kuno',NULL,NULL,NULL,NULL,NULL,'Fokus pada mode render standar browser.','go',9,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(2,1,'question','Aturan Penggunaan Tag Heading h1 untuk SEO','Berdasarkan standar praktik terbaik optimasi mesin pencari (SEO) dan struktur semantik HTML5, berapakah jumlah tag `<h1>` yang direkomendasikan berada dalam satu halaman web tunggal?','[\"Bebas sebanyak-banyaknya sesuai selera desain\", \"Tepat SATU tag <h1> per halaman\", \"Minimal 3 tag agar halaman mudah ditemukan di Google\", \"Tidak boleh menggunakan <h1> sama sekali jika sudah ada tag title\"]','Tepat SATU tag <h1> per halaman',NULL,NULL,NULL,NULL,NULL,'Hanya ada satu tajuk utama topik per halaman.','go',10,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(3,1,'question','Fungsi Atribut alt pada Tag Gambar <img>','Manakah fungsi utama yang paling tepat dari atribut `alt` pada elemen `<img>`?','[\"Menentukan efek animasi perputaran gambar saat di-hover\", \"Memberikan teks deskriptif alternatif saat gambar gagal dimuat dan dibacakan oleh pembaca layar (screen reader) bagi penyandang disabilitas\", \"Mengubah resolusi gambar secara otomatis menjadi format vector SVG\", \"Mengompres ukuran byte file gambar sebelum diunggah ke hosting\"]','Memberikan teks deskriptif alternatif saat gambar gagal dimuat dan dibacakan oleh pembaca layar (screen reader) bagi penyandang disabilitas',NULL,NULL,NULL,NULL,NULL,'alt singkatan dari alternative text untuk aksesibilitas.','go',11,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(4,1,'question','Keamanan Tautan Tab Baru (rel noopener)','Ketika membuat tautan eksternal yang membuka tab peramban baru menggunakan `target=\"_blank\"`, pasangan atribut keamanan manakah yang wajib disertakan untuk mencegah celah keamanan reverse tabnabbing?','[\"security=\\\"high\\\"\", \"rel=\\\"noopener noreferrer\\\"\", \"sandbox=\\\"secure-tab\\\"\", \"protect=\\\"window-lock\\\"\"]','rel=\"noopener noreferrer\"',NULL,NULL,NULL,NULL,NULL,'Menggunakan atribut rel yang memblokir window.opener.','go',12,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(5,1,'question','Tag Semantik untuk Konten Mandiri Independen','Elemen semantik HTML5 manakah yang paling tepat digunakan untuk membungkus sebuah konten mandiri yang dapat didistribusikan ulang atau berdiri sendiri secara utuh, seperti postingan blog, artikel berita, atau komentar pembaca?','[\"<section>\", \"<article>\", \"<aside>\", \"<div>\"]','<article>',NULL,NULL,NULL,NULL,NULL,'Berarti artikel mandiri.','go',13,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(6,1,'question','Elemen Semantik Menu Navigasi Utama','Elemen semantik HTML5 manakah yang secara resmi ditetapkan oleh standar W3C untuk mengelompokkan tautan navigasi utama pada sebuah website?','[\"<menu>\", \"<nav>\", \"<navbar>\", \"<links>\"]','<nav>',NULL,NULL,NULL,NULL,NULL,'Singkatan tiga huruf dari navigation.','go',14,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(7,1,'question','Atribut Wajib Isi pada Formulir HTML','Atribut HTML5 manakah yang digunakan pada elemen input formulir untuk menandai bahwa bidang tersebut wajib diisi oleh pengguna sebelum formulir diizinkan dikirim?','[\"validate\", \"mandatory\", \"required\", \"important\"]','required',NULL,NULL,NULL,NULL,NULL,'Berasal dari kata required (diwajibkan).','go',15,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(8,1,'question','Fungsi Elemen Meta Viewport','Apakah tujuan utama menyertakan tag `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">` pada bagian `<head>` dokumen HTML?','[\"Mempercepat kecepatan unduh gambar dari CDN\", \"Mengatur skala lebar layar agar tampilan responsif di berbagai perangkat ponsel pintar\", \"Mencegah pengguna melakukan klik kanan pada halaman website\", \"Menyambungkan file lembar gaya CSS secara otomatis\"]','Mengatur skala lebar layar agar tampilan responsif di berbagai perangkat ponsel pintar',NULL,NULL,NULL,NULL,NULL,'Mengatur skala lebar viewport layar mobile.','go',16,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(9,1,'question','Pengoptimalan Kinerja Gambar dengan loading lazy','Apakah fungsi dari atribut `loading=\"lazy\"` pada elemen `<img>` modern?','[\"Memberikan efek animasi gambar muncul perlahan (fade-in)\", \"Menunda pengunduhan gambar sampai pengguna menggulir layar mendekati posisi gambar tersebut untuk menghemat bandwidth\", \"Mengurangi resolusi warna gambar menjadi hitam putih saat koneksi lambat\", \"Menghapus gambar dari server setelah dilihat satu kali oleh pengunjung\"]','Menunda pengunduhan gambar sampai pengguna menggulir layar mendekati posisi gambar tersebut untuk menghemat bandwidth',NULL,NULL,NULL,NULL,NULL,'Lazy loading menunda proses pengunduhan aset yang belum tampak di layar.','go',17,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(10,1,'question','Elemen Semantik untuk Konten Sampingan (Sidebar)','Manakah elemen semantik HTML5 yang paling tepat digunakan untuk membungkus konten pendukung yang berhubungan secara tidak langsung dengan konten utama, seperti profil singkat penulis, daftar tautan populer, atau banner sponsor?','[\"<aside>\", \"<sidebar>\", \"<section>\", \"<nav>\"]','<aside>',NULL,NULL,NULL,NULL,NULL,'Berada di samping (aside).','go',18,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(11,1,'coding','Tantangan Coding 1: Generator Tag Meta Deskripsi SEO','Dalam sistem manajemen konten (CMS), teks deskripsi yang diinput penulis harus diubah menjadi tag meta HTML standar SEO:\n`<meta name=\"description\" content=\"...\">`.\n\n### Instruksi:\nBuatlah program JavaScript yang membaca 1 baris teks deskripsi dari pengguna, lalu cetak teks tersebut dalam format tag meta HTML lengkap tanpa spasi tambahan.\n\nContoh Input:\n`Belajar HTML5 dari dasar sampai mahir bersama TalentGroup`\n\nContoh Output yang Diharapkan:\n`<meta name=\"description\" content=\"Belajar HTML5 dari dasar sampai mahir bersama TalentGroup\">`',NULL,NULL,NULL,'const readline = require(\'readline\');\nconst rl = readline.createInterface({ input: process.stdin, output: process.stdout });\n\nrl.on(\'line\', (line) => {\n    const text = line.trim();\n    console.log(\'<meta name=\"description\" content=\"\' + text + \'\">\');\n    process.exit(0);\n});','<meta name=\\\"description\\\" content=\\\"Belajar HTML5 dari dasar sampai mahir bersama TalentGroup\\\">','[\"console_log\"]','[{\"input\": \"Belajar HTML5 dari dasar sampai mahir bersama TalentGroup\", \"expected_output\": \"<meta name=\\\\\\\"description\\\\\\\" content=\\\\\\\"Belajar HTML5 dari dasar sampai mahir bersama TalentGroup\\\\\\\">\"}, {\"input\": \"Panduan Form Web & Aksesibilitas Modern\", \"expected_output\": \"<meta name=\\\\\\\"description\\\\\\\" content=\\\\\\\"Panduan Form Web & Aksesibilitas Modern\\\\\\\">\"}]','Gabungkan string pembuka tag meta dengan nilai teks input dan tutup dengan tanda kutip.','javascript',19,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(12,1,'coding','Tantangan Coding 2: Generator Tautan Semantik Ramah SEO','Dalam pembuatan menu navigasi, kita perlu mengubah teks menu dan URL tujuan menjadi elemen tautan HTML: `<a href=\"URL\">TEKS</a>`.\n\n### Instruksi:\nBuatlah program JavaScript yang membaca 1 baris input berisi URL dan Teks Menu yang dipisahkan oleh tanda koma (`,`), lalu cetak format tag `<a>` HTML lengkap.\n\nContoh Input:\n`/kursus,Daftar Kursus`\n\nContoh Output:\n`<a href=\"/kursus\">Daftar Kursus</a>`',NULL,NULL,NULL,'const readline = require(\'readline\');\nconst rl = readline.createInterface({ input: process.stdin, output: process.stdout });\n\nrl.on(\'line\', (line) => {\n    const parts = line.trim().split(\',\');\n    const url = parts[0].trim();\n    const text = parts[1].trim();\n    \n    console.log(\'<a href=\"\' + url + \'\">\' + text + \'</a>\');\n    process.exit(0);\n});','<a href=\\\"/kursus\\\">Daftar Kursus</a>','[\"console_log\"]','[{\"input\": \"/kursus,Daftar Kursus\", \"expected_output\": \"<a href=\\\\\\\"/kursus\\\\\\\">Daftar Kursus</a>\"}, {\"input\": \"https://talentgroup.id,Portal Edukasi\", \"expected_output\": \"<a href=\\\\\\\"https://talentgroup.id\\\\\\\">Portal Edukasi</a>\"}]','Gunakan .split(\",\") untuk memisahkan URL dan Teks, lalu susun tag <a>.','javascript',20,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(13,2,'question','Selektor dengan Bobot Specificity Tertinggi','Dari keempat jenis selektor CSS berikut, manakah yang memiliki bobot Specificity (prioritas penimpaan gaya) paling tinggi dalam menentukan tampilan elemen?','[\"Elemen tag standar seperti h1 atau p (1 poin)\", \"Class Selector seperti .card-container (10 poin)\", \"Identifier unik ID Selector seperti #navbar-utama (100 poin)\", \"Pseudo-class seperti :hover atau :focus (10 poin)\"]','Identifier unik ID Selector seperti #navbar-utama (100 poin)',NULL,NULL,NULL,NULL,NULL,'ID Selector memiliki bobot 100 poin.','go',9,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(14,2,'question','Perilaku Properti box-sizing: border-box','Bagaimanakah browser menghitung total dimensi elemen saat dideklarasikan properti `box-sizing: border-box`?','[\"Padding dan border akan dihitung di luar ukuran width/height yang ditetapkan\", \"Nilai margin elemen secara otomatis dikonversi menjadi padding internal\", \"Nilai padding dan border disertakan ke dalam total ukuran width dan height elemen\", \"Elemen secara otomatis berubah format menjadi elemen inline murni\"]','Nilai padding dan border disertakan ke dalam total ukuran width dan height elemen',NULL,NULL,NULL,NULL,NULL,'Padding dan border melebur ke dalam ukuran kotak.','go',10,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(15,2,'question','Properti Distribusi Ruang Flexbox (Main Axis)','Nilai properti `justify-content` manakah yang mendistribusikan item pertama persis menempel di tepi kiri dan item terakhir persis menempel di tepi kanan, sementara sisa ruang dibagi rata di antara item-item tengah?','[\"space-evenly\", \"space-around\", \"space-between\", \"center\"]','space-between',NULL,NULL,NULL,NULL,NULL,'Bermakna ruang di antara item (antara tepi ke tepi).','go',11,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(16,2,'question','Fungsi auto-fit pada CSS Grid Layout','Apakah keunggulan utama dari penggunaan nilai `auto-fit` dalam deklarasi `grid-template-columns: repeat(auto-fit, minmax(280px, 1fr))`?','[\"Menyembunyikan kartu jika resolusi layar berada di bawah 600px\", \"Memperluas dan menyesuaikan kolom yang ada secara otomatis mengisi seluruh ruang kosong layar tanpa media query\", \"Memutar orientasi layout dari horizontal menjadi vertikal secara acak\", \"Mengunci ukuran setiap elemen agar tidak pernah berubah sama sekali\"]','Memperluas dan menyesuaikan kolom yang ada secara otomatis mengisi seluruh ruang kosong layar tanpa media query',NULL,NULL,NULL,NULL,NULL,'Membuat layout responsif otomatis mengisi layar.','go',12,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(17,2,'question','Perilaku Position: Sticky','Bagaimanakah karakteristik elemen yang diberi deklarasi `position: sticky; top: 0;` saat halaman digulir (scroll)?','[\"Elemen langsung menghilang dari dokumen\", \"Elemen mengalir normal di dalam dokumen sampai posisi scroll menyentuh batas top 0, lalu menempel di bagian atas layar selama masih berada di dalam kontainer induknya\", \"Elemen selalu melayang di tengah layar kapanpun dan dimanapun\", \"Elemen terkunci secara permanen dan tidak dapat digulir sama sekali\"]','Elemen mengalir normal di dalam dokumen sampai posisi scroll menyentuh batas top 0, lalu menempel di bagian atas layar selama masih berada di dalam kontainer induknya',NULL,NULL,NULL,NULL,NULL,'Perpaduan sifat relative dan fixed.','go',13,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(18,2,'question','Satuan Ukuran rem vs px','Mengapa para profesional web lebih menyukai menggunakan satuan `rem` daripada `px` untuk ukuran font dan spasi?','[\"Karena satuan rem membuat file CSS berukuran lebih kecil\", \"Karena satuan rem bersifat relatif terhadap ukuran font akar (root html) sehingga otomatis menyesuaikan preferensi aksesibilitas pengguna\", \"Karena satuan px tidak lagi didukung oleh browser modern\", \"Karena satuan rem hanya dapat digunakan pada perangkat iPhone\"]','Karena satuan rem bersifat relatif terhadap ukuran font akar (root html) sehingga otomatis menyesuaikan preferensi aksesibilitas pengguna',NULL,NULL,NULL,NULL,NULL,'rem relatif terhadap root html.','go',14,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(19,2,'question','Properti Flexbox untuk Sumbu Silang (Cross Axis)','Properti CSS Flexbox manakah yang digunakan untuk mengatur perataan elemen-elemen anak di sepanjang sumbu silang (cross-axis)?','[\"justify-content\", \"align-items\", \"flex-direction\", \"flex-wrap\"]','align-items',NULL,NULL,NULL,NULL,NULL,'align-items mengatur posisi vertikal pada flex row default.','go',15,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(20,2,'question','Satuan Fractional Unit (fr) pada CSS Grid','Dalam sistem tata letak CSS Grid, apakah fungsi dari unit pecahan `fr` (fractional unit)?','[\"Satuan kecepatan animasi frame per detik\", \"Membagi sisa ruang kosong kontainer yang tersedia secara proporsional\", \"Mengatur tingkat transparansi latar belakang elemen\", \"Menentukan jumlah baris maksimum dalam satu dokumen\"]','Membagi sisa ruang kosong kontainer yang tersedia secara proporsional',NULL,NULL,NULL,NULL,NULL,'Membagi sisa ruang kosong secara fraksional.','go',16,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(21,2,'question','Fungsi CSS clamp() untuk Tipografi Cairan','Apakah parameter yang diterima oleh fungsi CSS `clamp(A, B, C)` secara berurutan?','[\"Maksimum, Ideal, Minimum\", \"Minimum, Nilai Ideal (Preferred), Maksimum\", \"Warna, Ketebalan, Gaya Garis\", \"Padding, Border, Margin\"]','Minimum, Nilai Ideal (Preferred), Maksimum',NULL,NULL,NULL,NULL,NULL,'clamp(min, preferred, max).','go',17,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(22,2,'question','Mekanisme CSS Custom Properties (Variabel)','Bagaimanakah sintaks baku untuk memanggil nilai dari variabel CSS yang dideklarasikan dengan nama `--primary-color`?','[\"$primary-color\", \"@primary-color\", \"var(--primary-color)\", \"get(--primary-color)\"]','var(--primary-color)',NULL,NULL,NULL,NULL,NULL,'Menggunakan fungsi var().','go',18,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(23,2,'coding','Tantangan Coding 1: Hitung Dimensi Total Elemen (Content-Box)','Pada mode bawaan `box-sizing: content-box`, total lebar elemen dihitung dengan rumus:\n`Total Width = Width + (Padding * 2) + (Border * 2)`\n\n### Instruksi:\nBuatlah program JavaScript yang membaca 3 input angka dalam 1 baris dipisahkan spasi:\n`Width Padding Border`\n\nHitung dan cetak angka total lebar elemen!\n\nContoh Input:\n`200 20 2`\n\nKalkulasi: `200 + (20 * 2) + (2 * 2) = 244`\n\nContoh Output:\n`244`',NULL,NULL,NULL,'const readline = require(\'readline\');\nconst rl = readline.createInterface({ input: process.stdin, output: process.stdout });\n\nrl.on(\'line\', (line) => {\n    const [width, padding, border] = line.trim().split(/\\s+/).map(Number);\n    const total = width + (padding * 2) + (border * 2);\n    console.log(total);\n    process.exit(0);\n});','244','[\"console_log\"]','[{\"input\": \"200 20 2\", \"expected_output\": \"244\"}, {\"input\": \"300 15 5\", \"expected_output\": \"340\"}]','Kalikan padding dan border dengan 2, lalu tambahkan ke width.','javascript',19,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(24,2,'coding','Tantangan Coding 2: Hitung Ketinggian Video Rasio Aspek 16:9','Dalam CSS responsif, kita menentukan ketinggian video dengan rasio 16:9 menggunakan rumus:\n`Height = Math.round((Width * 9) / 16)`\n\n### Instruksi:\nBuatlah program JavaScript yang membaca input 1 angka lebar (Width dalam pixel), lalu cetak ketinggian elemen 16:9 dalam angka bulat!\n\nContoh Input:\n`1920`\n\nContoh Output:\n`1080`',NULL,NULL,NULL,'const readline = require(\'readline\');\nconst rl = readline.createInterface({ input: process.stdin, output: process.stdout });\n\nrl.on(\'line\', (line) => {\n    const width = parseFloat(line.trim());\n    const height = Math.round((width * 9) / 16);\n    console.log(height);\n    process.exit(0);\n});','1080','[\"console_log\"]','[{\"input\": \"1920\", \"expected_output\": \"1080\"}, {\"input\": \"1280\", \"expected_output\": \"720\"}]','Kalikan width dengan 9, bagi 16, lalu bulatkan dengan Math.round().','javascript',20,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(25,3,'question','Cakupan Variabel const dan let dalam ES6','Perhatikan cuplikan kode JavaScript modern berikut:\n\n```javascript\nfunction periksaKondisi() {\n    if (true) {\n        let nilaiX = 100;\n        const nilaiY = 200;\n    }\n    console.log(nilaiX, nilaiY);\n}\nperiksaKondisi();\n```\n\nApa yang akan terjadi ketika fungsi di atas dijalankan di console browser?','[\"100 200\", \"undefined undefined\", \"ReferenceError: nilaiX is not defined\", \"null null\"]','ReferenceError: nilaiX is not defined',NULL,NULL,NULL,NULL,NULL,'let dan const memiliki block scope di dalam kurung kurawal {}.','go',9,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(26,3,'question','Prinsip Kesetaraan Ketat (Strict Equality)','Berdasarkan aturan penanganan tipe data JavaScript, ekspresi mana di bawah ini yang akan menghasilkan nilai boolean `true`?','[\"0 === false\", \"5 === \\\"5\\\"\", \"null === undefined\", \"5 !== \\\"5\\\"\"]','5 !== \"5\"',NULL,NULL,NULL,NULL,NULL,'!== mengevaluasi ketidaksamaan tipe maupun nilai.','go',10,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(27,3,'question','Transformasi Data Menggunakan Array.prototype.map()','Diberikan sebuah array angka: `const data = [2, 4, 6];`.\n\nJika kita mengeksekusi kode: `const hasil = data.map(n => n * 3);`, apa output dari variabel `hasil` dan status array asli `data`?','[\"hasil bernilai [6, 12, 18], dan array data berubah menjadi [6, 12, 18]\", \"hasil bernilai [6, 12, 18], dan array data tetap [2, 4, 6]\", \"hasil bernilai 36 (penjumlahan), dan data tetap [2, 4, 6]\", \"hasil bernilai boolean true\"]','hasil bernilai [6, 12, 18], dan array data tetap [2, 4, 6]',NULL,NULL,NULL,NULL,NULL,'map() bersifat immutable dan mengembalikan array baru.','go',11,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(28,3,'question','Perbedaan Array filter() vs find()','Jika Anda memiliki daftar objek pengguna dan ingin mengambil SATU objek pengguna pertama yang memiliki properti `id === 42`, metode array manakah yang paling tepat dan efisien digunakan?','[\"daftarPengguna.map(u => u.id === 42)\", \"daftarPengguna.reduce(u => u.id === 42)\", \"daftarPengguna.find(u => u.id === 42)\", \"daftarPengguna.filter(u => u.id === 42)\"]','daftarPengguna.find(u => u.id === 42)',NULL,NULL,NULL,NULL,NULL,'find() langsung berhenti saat menemukan elemen pertama yang cocok.','go',12,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(29,3,'question','Kalkulasi Akumulator dengan Array.prototype.reduce()','Perhatikan kode kalkulasi total belanja berikut:\n\n```javascript\nconst keranjang = [10000, 20000, 30000];\nconst total = keranjang.reduce((acc, curr) => acc + curr, 5000);\n```\n\nBerapakah nilai akhir dari variabel `total`?','[\"60000\", \"65000\", \"5000\", \"Error: NaN\"]','65000',NULL,NULL,NULL,NULL,NULL,'Nilai awal akumulator adalah 5000.','go',13,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(30,3,'question','Mencegah Reload Halaman pada Event Form Submit','Saat membuat antarmuka web interaktif berbasis JavaScript, metode event apa yang WAJIB dipanggil di dalam listener submit form agar browser tidak melakukan refresh otomatis ke URL action?','[\"event.stopPropagation()\", \"event.preventDefault()\", \"document.stopReload()\", \"window.freezeForm()\"]','event.preventDefault()',NULL,NULL,NULL,NULL,NULL,'Mencegah aksi bawaan browser.','go',14,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(31,3,'question','Keunggulan Nullish Coalescing (??) atas Logical OR (||)','Diberikan kode pengaturan konfigurasi berikut:\n\n```javascript\nconst kuotaTersisa = 0;\nconst kuotaA = kuotaTersisa || 10;\nconst kuotaB = kuotaTersisa ?? 10;\n```\n\nBerapakah nilai dari `kuotaA` dan `kuotaB` berturut-turut?','[\"kuotaA = 0, kuotaB = 0\", \"kuotaA = 10, kuotaB = 10\", \"kuotaA = 10, kuotaB = 0\", \"kuotaA = 0, kuotaB = 10\"]','kuotaA = 10, kuotaB = 0',NULL,NULL,NULL,NULL,NULL,'?? hanya memeriksa null dan undefined, mempertahankan 0.','go',15,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(32,3,'question','Karakteristik Lexical Binding this pada Arrow Functions','Manakah pernyataan yang PALING TEPAT mengenai kata kunci `this` di dalam sebuah Arrow Function?','[\"Arrow function selalu membuat konteks this baru yang mengikat objek global window\", \"Arrow function tidak memiliki this sendiri; ia mewarisi this dari scope leksikal lingkungan tempat ia dibuat\", \"Kata kunci this di dalam arrow function nilainya selalu undefined\", \"Nilai this di arrow function dapat diubah secara bebas menggunakan method .bind()\"]','Arrow function tidak memiliki this sendiri; ia mewarisi this dari scope leksikal lingkungan tempat ia dibuat',NULL,NULL,NULL,NULL,NULL,'Lexical scoping mewarisi konteks pembungkus di luarnya.','go',16,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(33,3,'question','Mekanisme Penyebaran Event (Event Bubbling) pada DOM','Ketika seorang pengguna mengklik sebuah elemen tombol `<button class=\"btn-hapus\">` yang berada di dalam pembungkus `<div class=\"kartu\">`, bagaimanakah alur penjalaran event secara default?','[\"Event hanya dieksekusi pada button dan berhenti seketika secara otomatis\", \"Event pertama kali aktif di window, lalu turun ke body, dan berhenti di div\", \"Event dipicu pertama kali pada button sasaran, kemudian merembet naik (bubble) ke div induk hingga dokumen terluar\", \"Event terjadi secara acak pada seluruh elemen di layar\"]','Event dipicu pertama kali pada button sasaran, kemudian merembet naik (bubble) ke div induk hingga dokumen terluar',NULL,NULL,NULL,NULL,NULL,'Event merambat naik dari target paling dalam ke leluhur (ancestors).','go',17,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(34,3,'question','Penanganan Error Asynchronous dengan Async/Await','Konstruksi standar manakah yang digunakan di JavaScript modern untuk menangkap dan menangani kegagalan jaringan atau parsing saat menggunakan `async/await`?','[\"Blok try { ... } catch (error) { ... }\", \"Fungsi onError() bawaan window\", \"Pernyataan if (await === error)\", \"Blok while (isPending) { retry(); }\"]','Blok try { ... } catch (error) { ... }',NULL,NULL,NULL,NULL,NULL,'Menggunakan blok standar try-catch.','go',18,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(35,3,'coding','Tantangan Algoritma: Saring Bilangan Genap dan Kuadratkan','Kamu diminta membuat program untuk memproses daftar angka masukan.\n\nAturan Pemrosesan:\n1. Baris pertama input adalah N (jumlah angka).\n2. Baris berikutnya berisi N angka bulat.\n3. Saring dan ambil HANYA angka yang bernilai GENAP.\n4. Kuadratkan setiap angka genap tersebut (angka * angka).\n5. Cetak total penjumlahan dari seluruh hasil kuadrat tersebut.\n\nContoh Input:\n4\n1\n2\n3\n4\n\nPenjelasan:\nAngka genap: 2 dan 4.\nHasil kuadrat: 2^2 = 4, 4^2 = 16.\nTotal penjumlahan: 4 + 16 = 20.\n\nFormat Output:\nCetak satu angka integer hasil penjumlahan.',NULL,NULL,'package main\n\nimport (\n	\"fmt\"\n)\n\nfunc main() {\n	var n int\n	if _, err := fmt.Scan(&n); err != nil {\n		return\n	}\n\n	total := 0\n	for i := 0; i < n; i++ {\n		var val int\n		fmt.Scan(&val)\n		if val%2 == 0 {\n			total += (val * val)\n		}\n	}\n\n	fmt.Println(total)\n}\n','package main\n\nimport (\n	\"fmt\"\n)\n\nfunc main() {\n	var n int\n	fmt.Scan(&n)\n\n	total := 0\n	for i := 0; i < n; i++ {\n		var val int\n		fmt.Scan(&val)\n		// Lengkapi logika: jika val genap, tambahkan kuadratnya ke total\n	}\n\n	fmt.Println(total)\n}\n','20',NULL,'[{\"input\": \"4\\n1\\n2\\n3\\n4\", \"expected_output\": \"20\"}, {\"input\": \"5\\n2\\n4\\n6\\n8\\n10\", \"expected_output\": \"220\"}, {\"input\": \"3\\n1\\n3\\n5\", \"expected_output\": \"0\"}]','Gunakan modulus (val % 2 == 0) untuk memeriksa bilangan genap.','go',19,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(36,3,'coding','Kalkulator Diskon Belanja Kasir Otomatis','Sebuah minimarket membutuhkan program kasir otomatis. Kamu diminta membuat program untuk menjumlahkan semua harga barang yang dibeli oleh pelanggan.\n\nAturan Promo:\nJika total belanja pelanggan LEBIH DARI Rp 100.000, pelanggan berhak mendapatkan diskon sebesar 10% dari total belanja. Jika kurang dari atau sama dengan 100.000, tidak ada diskon.\n\nFormat Input:\nBaris pertama adalah N (jumlah barang).\nN baris berikutnya adalah harga masing-masing barang (angka desimal / float).\n\nFormat Output:\nCetak total harga yang harus dibayar setelah diskon menggunakan format dua angka di belakang koma (contoh: 99000.00).',NULL,NULL,'package main\n\nimport (\n	\"fmt\"\n)\n\nfunc main() {\n	var n int\n	if _, err := fmt.Scan(&n); err != nil {\n		return\n	}\n\n	var total float64\n	for i := 0; i < n; i++ {\n		var harga float64\n		fmt.Scan(&harga)\n		total += harga\n	}\n\n	if total > 100000.0 {\n		total = total * 0.90\n	}\n\n	fmt.Printf(\"%.2f\\n\", total)\n}\n','package main\n\nimport (\n	\"fmt\"\n)\n\nfunc main() {\n	var n int\n	fmt.Scan(&n)\n\n	var total float64\n	for i := 0; i < n; i++ {\n		var harga float64\n		fmt.Scan(&harga)\n		total += harga\n	}\n\n	// Lengkapi aturan diskon 10% jika total > 100000\n	fmt.Printf(\"%.2f\\n\", total)\n}\n','99000.00',NULL,'[{\"input\": \"3\\n50000\\n40000\\n20000\", \"expected_output\": \"99000.00\"}, {\"input\": \"2\\n30000\\n50000\", \"expected_output\": \"80000.00\"}, {\"input\": \"1\\n200000\", \"expected_output\": \"180000.00\"}]','Periksa kondisi jika total > 100000 kalikan dengan 0.90.','go',20,'2026-10-24 20:00:31','2026-10-24 20:00:31');
