INSERT INTO `module_categories` VALUES (1,'Modul HTML5 & Web Semantik','modul-html5-dan-web-semantik','Panduan komprehensif struktur standar industri W3C, meta tag SEO, formulir validasi, dan arsitektur aksesibilitas digital.',1,NULL,NULL,'globe','#f97316','HTML5 Core',1,1,1,1,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(2,'Modul CSS3 & Layout Modern','modul-css3-dan-layout-modern','Kuasai seni menata layout web responsif, universal box-sizing, Flexbox 1D, CSS Grid 2D, variabel tema, dan animasi transisi.',1,NULL,NULL,'palette','#3b82f6','CSS3 Master',2,1,1,1,'2026-10-24 20:00:31','2026-10-24 20:00:31'),(3,'Modul JavaScript Modern & DOM','modul-javascript-modern-dan-dom','Panduan komprehensif sintaks modern ES6+, logika percabangan, manipulasi array fungsional, event handling DOM, dan asynchronous Fetch API.',1,NULL,NULL,'code','#eab308','JS Modern',3,1,1,1,'2026-10-24 20:00:31','2026-10-24 20:00:31');
